@push('scripts')
<script>(()=>{const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'₱'+Number(n||0).toFixed(2);let token=localStorage.getItem('fh_waiter_token')||'',user=null,products=[],cart=[];async function api(u,o={}){const r=await fetch(u,{...o,headers:{Accept:'application/json','Content-Type':'application/json',Authorization:'Bearer '+token,...(o.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.message||Object.values(d.errors||{}).flat().join(' ')||'Request failed');return d}function render(){const c=cart.reduce((a,x)=>a+x.quantity,0);$('cart').innerHTML=cart.length?cart.map((x,i)=>`<div class="d-flex justify-content-between align-items-center py-2"><div><b>${esc(x.name)}</b><div class="small">${x.quantity} × ${money(x.unit_price)}</div></div><div class="btn-group btn-group-sm"><button class="btn btn-outline-secondary" onclick="qty(${i},-1)">−</button><button class="btn btn-outline-secondary" onclick="qty(${i},1)">+</button></div></div>`).join('')+`<hr><div class="d-flex justify-content-between fw-bold"><span>Total</span><span>${money(cart.reduce((a,x)=>a+x.unit_price*x.quantity,0))}</span></div>`:'<div class="text-secondary py-4">Cart is empty.</div>'}window.qty=(i,d)=>{cart[i].quantity+=d;if(cart[i].quantity<1)cart.splice(i,1);render()};function show(){ $('login').classList.add('d-none');$('app').classList.remove('d-none');$('branchName').textContent=user?.branch?.name||'Assigned branch';$('products').innerHTML=products.map(p=>`<div class="col-md-6"><div class="card food-card p-3 h-100"><span class="small accent">${esc(p.category?.name)}</span><h5 class="fw-bold">${esc(p.name)}</h5><div class="d-flex justify-content-between align-items-center mt-3"><b>${money(p.base_price)}</b><button class="btn btn-sm btn-fh" onclick="add(${p.id})">Add</button></div></div></div>`).join('')||'<div class="col-12 text-secondary">No products.</div>';render()}window.add=id=>{const p=products.find(x=>x.id===id);if(!p)return;const x=cart.find(x=>x.product_id===id);if(x)x.quantity++;else cart.push({product_id:id,name:p.name,unit_price:Number(p.base_price),quantity:1});render()};async function login(){try{const r=await fetch('/api/v1/auth/login',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({email:$('email').value,password:$('password').value})});const d=await r.json();if(!r.ok)throw Error(d.message||'Login failed');if(d.user?.role!=='waiter')throw Error('This portal requires a waiter account.');if(!d.user?.branch_id)throw Error('This waiter account has no branch assigned.');localStorage.removeItem('fh_admin_token');localStorage.removeItem('fh_branch_token');localStorage.removeItem('fh_kitchen_token');localStorage.removeItem('fh_customer_token');localStorage.removeItem('fh_rider_token');token=d.token;user=d.user;localStorage.setItem('fh_waiter_token',token);products=await api('/api/v1/products?branch_id='+encodeURIComponent(user.branch_id));show();}catch(e){$('msg').textContent=e.message;$('msg').className='small mt-2 text-danger'}}$('form').addEventListener('submit',e=>{e.preventDefault();login()});$('place').onclick=async()=>{if(!cart.length)return;$('place').disabled=true;try{const d=await api('/api/v1/pos/orders',{method:'POST',body:JSON.stringify({branch_id:user.branch_id,items:cart.map(x=>({product_id:x.product_id,quantity:x.quantity,options:[]})),payment_method:$('payment').value})});$('orderMsg').textContent='POS order '+d.order_number+' created.';$('orderMsg').className='small mt-3 text-success';cart=[];render()}catch(e){$('orderMsg').textContent=e.message;$('orderMsg').className='small mt-3 text-danger'}finally{$('place').disabled=false}};$('logout').onclick=async()=>{try{await fetch('/api/v1/auth/logout',{method:'POST',headers:{Authorization:'Bearer '+token,Accept:'application/json'}})}catch(e){}localStorage.removeItem('fh_waiter_token');location.reload()};if(token){api('/api/v1/me').then(async u=>{if(u.role!=='waiter'||!u.branch_id)throw Error('Saved waiter session is invalid.');user=u;products=await api('/api/v1/products?branch_id='+encodeURIComponent(user.branch_id));show()}).catch(()=>{localStorage.removeItem('fh_waiter_token');token=''})}})();</script>
